    faq_a_bag_examples_list: "กระเป๋าใหม่มาพร้อมตัวอย่างที่แก้ไขหรือลบได้เหมือนทุกอย่าง: บ้าน (ของที่ต้องซื้อ สูตรอาหาร เมนูประจำสัปดาห์) ครอบครัว (ช่วงเวลาเล็ก ๆ รายการสำหรับปาร์ตี้วันเกิด กิจกรรมและคลาสเรียน) ไอเดีย (ไอเดียวันหยุดสุดสัปดาห์ ไอเดียของขวัญตามความสนิทกับคนคนนั้น และจะทำอะไรกับเงินที่เก็บไว้) และการเดินทาง (ที่ที่อยากไป ของที่ต้องเตรียมไปเที่ยว ของไปพักโรงแรม และรายการบินไปต่างประเทศ) กระเป๋าที่มีอยู่แล้วจะได้รับตัวอย่างล่าสุดหนึ่งครั้ง ใส่ลงในช่องของกระเป๋าเอง",
