    faq_a_nm_me1_guide: "Me – ตัวละครของคุณใน New Me ในร่างแรก (Me1) ครั้งแรก ทันทีหลังเข้าร่วม ประตูแสงจะเปิดออกพร้อมประกายระยิบระยับรอบด้าน และ Me บินออกมา อธิบายด้วยการแตะไม่กี่ครั้งว่ามีอะไรรออยู่ แล้วอยู่ข้างทุกคำถาม: ระหว่างเลือกมื้ออาหาร Me จะเขียนในหนังสือของตัวเองไปพร้อมกับคุณ และการแตะคำแนะนำจะแสดงคำแนะนำอื่น ตอนท้าย Me จะฉลองกับคุณและพาไปทัวร์สั้น ๆ – และเมื่อทัวร์จบ Me ยังมีอีกหนึ่งช่วงเวลาเล็ก ๆ กับคุณ ถ้าออกไปกลางคัน – ระหว่างคำถามหรือระหว่างทัวร์ – ครั้งหน้า Me จะดีใจที่ได้เจอคุณและถามว่าจะไปต่อจากจุดเดิมไหม \"ข้าม\" ด้านบนใช้ข้ามช่วงเปิดตัว",
