    faq_a_shop_holidays: "ในรายการซื้อของ แตะรูปของขวัญ: เทศกาลของประเทศที่เลือกไว้ในการตั้งค่าจะแสดงเรียงตามลำดับพร้อมวันที่ – ซึ่งคำนวณให้เองทุกปี แตะเทศกาลเพื่อเปิดรายการสำเร็จรูปของสิ่งที่คนนิยมซื้อในเทศกาลนั้น ทุกอย่างถูกเลือกไว้แล้ว (ยกเว้นของที่มีอยู่ในรายการแล้ว) เอาเครื่องหมายออกจากสิ่งที่ไม่ต้องการ แล้วแตะ “เพิ่มลงรายการ” สองสัปดาห์ก่อนเทศกาลจะมีการ์ดเล็กๆ ขึ้นที่ด้านบนของรายการ แตะ ✕ เพื่อซ่อนไว้จนถึงเทศกาลถัดไป",
