    shop_hol_items_title: "{holiday} – ซื้ออะไรดี?",
    shop_hol_not_now: "ไว้ทีหลัง",
    faq_a_shop_delivery: "ในรายการซื้อของ แตะรูปรถบรรทุก: เลือกว่ามีอะไรในออเดอร์ (เลือกไว้ทั้งหมดแล้ว) มาถึงเมื่อไร – วันนี้ พรุ่งนี้ หรือวันอื่น – และช่วงเวลาไหน (ช่วงเช้า ช่วงบ่าย ช่วงเย็น หรือ “อื่นๆ…” เพื่อกำหนดเวลาเอง) สินค้าเหล่านั้นจะย้ายไปอยู่ในการ์ด “กำลังมา” ที่ด้านบนของรายการ พร้อมวันและช่วงเวลา เมื่อถึงวันนั้น “เดลิเวอรีมาถึงหรือยัง?” จะขึ้นในวันของฉัน (และบนการ์ดมี “มาถึงหรือยัง?”) ถ้ามาครบ สินค้าจะย้ายไปที่ “ซื้ออีกครั้ง” ถ้ามีของขาด แตะของที่ไม่มา แล้วของนั้นจะกลับเข้ารายการทันที",
    faq_a_shop_departments: "รายการจะจัดเรียงตัวเองตามแผนกในซูเปอร์มาร์เก็ต – ผักและผลไม้ ขนมปัง นมและไข่ เนื้อสัตว์และปลา ของแห้ง อาหารแช่แข็ง เครื่องดื่ม ขนมขบเคี้ยว ทำความสะอาด ของใช้ส่วนตัว ของใช้เด็ก และสัตว์เลี้ยง – จะได้เดินไปตามทางเดินตามลำดับ แผนกจะรู้จากชื่อสินค้า ถ้าสินค้าไปอยู่ผิดที่ แตะที่สินค้าแล้วเลือกแผนก หรือเลือก “อื่นๆ…” เพื่อเขียนเอง",
    faq_a_shop_share_qty: "ได้ ข้างสินค้าแต่ละชิ้น + จะเพิ่มอีกหนึ่ง (×2, ×3…) และ − จะลดหนึ่ง ปุ่มแชร์ที่ด้านบนของรายการซื้อของจะส่งรายการทั้งหมดที่จัดเรียงตามแผนกอย่างเรียบร้อย ทาง WhatsApp อีเมล หรือคัดลอก",
    faq_a_shop_two_buttons: "ทั้งสองปุ่มหมายถึง “ซื้อแล้ว” ✕ ใช้กับของที่ซื้อครั้งเดียว – สินค้าจะออกจากรายการ (และรออยู่ในคลังเก็บ 🗑️ เผื่อกดผิด) ↺ ใช้กับของที่ซื้อซ้ำเรื่อยๆ – สินค้าจะออกจากรายการและไปรออยู่ใน “ซื้ออีกครั้ง” ซึ่งเปิดได้ด้วยปุ่ม ↺ เล็กๆ ข้างถังขยะที่ด้านล่างสุดของรายการ แตะครั้งเดียวที่นั่นก็จะพาสินค้ากลับเข้ารายการ ใน “แก้ไข” ข้างในสามารถเอาสินค้าออกได้ เวลาเพิ่มสินค้า ของที่เคยซื้อจะขึ้นมาเป็นคำแนะนำ และถ้ามีอยู่ในรายการแล้ว ก็จะกลายเป็น ×2 แทนที่จะเพิ่มอีกบรรทัด",
