    faq_a_new_me_challenge_journal: "เมื่อชาเลนจ์จบลง – ไม่ว่าจะเป็นชาเลนจ์ใหญ่ มินิชาเลนจ์ หรือชาเลนจ์ประจำสัปดาห์ – หน้าฉลองจะมีปุ่ม 📝 เป็นอย่างไรบ้าง? ซึ่งเปิดหน้าหนึ่งในสมุดบันทึกชาเลนจ์: รู้สึกอย่างไร (ห้าใบหน้า) อะไรช่วยได้ อะไรยาก และจะเก็บอะไรติดตัวไปต่อ – ไม่มีข้อไหนบังคับ และจะเขียนทีหลังก็ได้ สมุดบันทึกเป็นเพชรเม็ดหนึ่งในเป้วิเศษ: ทุกชาเลนจ์ที่จบแล้วพร้อมวันที่และสิ่งที่เขียนไว้ อันล่าสุดอยู่บนสุด – แตะอันหนึ่งเพื่ออ่าน แก้ไข หรือแชร์ (แชร์เฉพาะสิ่งที่อยู่บนหน้านั้น) ชาเลนจ์ที่จบแล้วยังได้เหรียญในความสำเร็จ ใต้ “ชาเลนจ์ที่ทำสำเร็จ” ด้วย สมุดบันทึกชาเลนจ์แยกจากไดอารี่",
