    faq_a_books_home_chip: "ได้ ในมุมอ่านหนังสือ บนการ์ดของหนังสือที่กำลังอ่าน ให้แตะ 📌 บนหน้าจอหลัก จะมีปุ่มเล็กๆ ที่แสดงหนังสือและหน้าปรากฏใต้คำทักทายบนหน้าจอหลัก – แตะที่ปุ่ม พิมพ์เลขหน้าใหม่แล้วบันทึก ความคืบหน้าจะถูกบันทึกไว้ (ในมุมอ่านหนังสือด้วย) แตะ 📌 อีกครั้งเพื่อเอาออก ปักหมุดได้หลายเล่มพร้อมกัน – เล่มละหนึ่งปุ่ม – และเหมือนกันในทุกอุปกรณ์",
    faq_a_new_me_week_challenge: "ชาเลนจ์เล็กๆ หนึ่งสัปดาห์ที่คุณเลือกเอง ในทางเดินมีการ์ดใหญ่ใบหนึ่ง: “สัปดาห์นี้อยากพัฒนาเรื่องอะไร?” – แตะที่การ์ด เลือกหมวด (กับตัวเอง กับผู้อื่น เรียนรู้และเติบโต ความสงบ ก้าวเล็กๆ แห่งความกล้า บ้านและกิจวัตร) และชาเลนจ์หนึ่งอย่าง แล้วเลือกว่าจะเริ่มเมื่อไหร่ ชาเลนจ์เดียวกันนี้ยังอยู่ในหน้าจอชาเลนจ์ ใต้ 🌱 การพัฒนาตนเอง ทุกวันกด ✓ บนการ์ด (มีวันพักหนึ่งวันต่อสัปดาห์) และทุกสัปดาห์ที่จบลงจะได้กุญแจดอกใหม่สำหรับโลกลับ “อ่านหนังสือวันละ 2 หน้า” จะถูกติ๊กให้เองจากหน้าที่บันทึกในมุมอ่านหนังสือ เมื่อสัปดาห์จบลง 📌 เก็บไว้เป็นภารกิจประจำวัน จะเพิ่มชาเลนจ์ไปที่กิจวัตรของฉันในเวลาที่เลือก พร้อม ✓ ทุกวัน ชาเลนจ์ประจำสัปดาห์ทำได้ทีละอย่าง ส่วนชาเลนจ์ใหญ่และมินิชาเลนจ์ยังดำเนินต่อไปควบคู่กัน",
    faq_a_room_genie: "ที่ระเบียงริมทะเล แตะตะเกียงของอะลาดินแล้วภูตแห่งป่าจะออกมา – และบทสนทนาก็เริ่มขึ้น: ความปรารถนาของคุณคืออะไร (อยากเปลี่ยนอะไรในชีวิต) จะรู้สึกอย่างไรเมื่อเป็นจริง อะไรยากระหว่างทาง และสถานการณ์ตอนนี้จะเปลี่ยนให้เป็นสิ่งดีได้อย่างไร จากนั้นคือใช้เวลานานประมาณเท่าไร ก้าวเล็กๆ ก้าวแรกและอีกสองก้าว และ “ถ้า… แล้ว…” สำหรับยามที่ยากขึ้น ในตอนท้ายความปรารถนาทั้งหมดจะปรากฏทีละก้าว และเปลี่ยนเป็นเป้าหมายใน เป้าหมายของฉัน ได้ (ขั้นตอนต่างๆ กลายเป็นหมุดหมายบนเส้นทาง พร้อมวันที่ตามระยะเวลาที่เลือก และแก้ไขทุกอย่างได้ที่นั่น) หรือบันทึกลงไดอารี่ก็ได้ – แล้วภูตก็จะกล่าวลา ถ้าไม่เลือกอย่างใดอย่างหนึ่ง จะไม่มีอะไรถูกบันทึก ตั้งแต่ครั้งที่สองเป็นต้นไป ภูตจะถามก่อนว่าอยากเปลี่ยนอะไรในชีวิตอีกไหม: อยาก – บทสนทนาเดิม; ตอนนี้ยังไม่ – ข้อความเตือนให้ทำเป้าหมายที่ตั้งไว้แล้วให้สำเร็จ ภูตออกมาวันละครั้ง: หลังจากบันทึกความปรารถนาแล้ว (หรือหลังจากเลือก “ตอนนี้ยังไม่”) ภูตจะพักจนถึงพรุ่งนี้ คำถามอิงจากวิธีที่รู้จักกันดีในการเปลี่ยนความปรารถนาให้เป็นแผน: ความปรารถนา ผลลัพธ์ อุปสรรค และแผน",
