    nm_me_choose: "เลือก",
    nm_me_on_screen: "บนหน้าจอ",
    faq_a_new_me_game: "ใน New Me ปุ่มเกมจะอยู่ที่เดิมเสมอ – ในทางเดิน ในห้องลับ และทุกที่ในป่า มีแค่ภาพวาดตรงกลางที่เปลี่ยน ด้านบน: วันที่เท่าไรของเส้นทาง กุญแจ สถิติต่อเนื่อง และพลังงานของวันนี้ (กินไปแล้วเท่าไรจากแผน) และใต้ลงมาคือภารกิจถัดไป – มื้อถัดไปตามเวลาของมื้อนั้น (แตะเพื่อเปิด พร้อม ✓ กินแล้ว) ด้านข้าง: ทั้งวัน ชาเลนจ์ และเส้นทางของฉัน และข้างๆ คือชาเลนจ์ประจำสัปดาห์ – 7 วันของชาเลนจ์และ ✓ สำหรับวันนี้ ด้านล่าง: เป้วิเศษ (New Me ทั้งหมด – แผนที่โลก เส้นทางของฉัน รายการซื้อของ ความสำเร็จ สมุดบันทึกชาเลนจ์ สัดส่วนร่างกาย รูปความคืบหน้า ปฏิทินรายเดือน ตารางรายวัน การแจ้งเตือน PDF เมนู และการตั้งค่า เปิดเป็นหน้าจอของตัวเอง) แผนที่โลก ซึ่งเป็นสิ่งแรกในเป้ แสดงทุกสถานที่ในป่า – แตะสถานที่เพื่อไปที่นั่น สถานที่ที่ล็อกอยู่จะบอกว่าต้องใช้กุญแจกี่ดอก Me คือตัวละครของคุณบนทางเดินในป่า: เริ่มจาก Me1 หลังผ่านชาเลนจ์ไม่กี่อย่าง (กุญแจ 4 ดอก) จะเติบโตเป็น Me2 และใกล้ตอนจบ (กุญแจ 9 ดอก) เป็น Me3 – พร้อมการแปลงโฉมที่ได้เห็นกับตา แตะ Me เพื่อดูทุกขั้น – ตัวละครที่ไปถึงแล้วเลือกใหม่ได้ทุกตัว ตัวละครก่อนหน้าจึงกลับมาได้ Me ลอยอยู่ – ลากด้วยนิ้วหรือเมาส์ แล้วทางเข้าที่แตะโดนจะเปิดออก (ทางเข้าที่ล็อกอยู่จะบอกว่าขาดกุญแจกี่ดอก) Me ยังตามไปทุกห้องและทุกสถานที่ และลอยอยู่ตรงที่วางไว้: ลากไปที่ไหนก็ได้ และลากวงแหวนเรืองแสงใต้ตัวเพื่อหมุนได้รอบตัว Me จะหันไปทางที่กำลังเคลื่อนที่ (บนคอมพิวเตอร์: ปุ่มลูกศรใช้เคลื่อนที่ Q และ E ใช้หมุน) ในทางเดิน ปุ่ม 🏠 เล็ก ๆ ใต้แถบด้านบนจะพากลับไปยังหน้าจอหลัก ส่วนในทุกห้องและทุกสถานที่ ปุ่มที่อยู่มุมเดียวกันจะพากลับไปยังทางเดิน",
