    faq_a_new_me_menu_build: "อย่างแรก แบบสอบถามจะถามว่ากินมื้อไหนบ้างและเวลาไหน (2 มื้อ + ของว่าง, 2 มื้อ + มื้อเย็นเบาๆ หรือทั้งสองอย่าง) และตอนเย็นมีอะไรไหม – กินหรือดื่ม อะไร และกี่โมง ถ้าเลือก “2 มื้อ + ของว่าง” มื้อหลักคือมื้อกลางวัน (11:30) และมื้อเย็น (19:00) ส่วนของว่างตอน 16:00 จากนั้นตัวเลือกทั้งหมดของมื้อเหล่านั้นจะขึ้นมา เลือกเมนูโปรดได้สูงสุด 2 อย่างต่อมื้อ – เมนูจะเขียนว่า “อันนี้หรืออันนั้น” ในบางตัวเลือก (พิต้ากับสเปรด, คอร์นเฟลกส์กับนม, อะไรเบาๆ) เลือกได้สูงสุด 3 อย่างที่ชอบ แต่ละอย่างมีปริมาณของตัวเอง และเมนูจะเขียนว่า “อันนี้หรืออันนั้นหรืออันโน้น” แคลอรีจะเป็นไปตามที่เลือก กาแฟและเครื่องดื่มก็เลือกแบบเดียวกัน ทุกตัวเลือกปรับสมดุลให้แล้ว รวมทั้งวันจึงได้ 1,300 หรือ 1,500 พอดี เปลี่ยนได้ทุกเมื่อ: ⚙️ การตั้งค่า → 🍽️ สร้างเมนูของคุณ หรือ “เลือกได้สูงสุด 3 อย่างที่ชอบ” บนการ์ดของมื้อนั้น",
    faq_q_new_me_menu_build: "เมนูของ New Me สร้างขึ้นอย่างไร?",
