    faq_a_myday_water_toggle: "ได้ แก้วน้ำใน ‘วันของฉัน’ (มี + สำหรับเพิ่มอีกแก้ว) แสดงเป็นค่าเริ่มต้น หากต้องการซ่อน ให้ปิด “แสดงน้ำใน ‘วันของฉัน’” ใน การตั้งค่า > การปรับแต่งและปฏิทิน ไม่มีอะไรถูกลบ – การติดตามการดื่มน้ำยังทำงานต่อ และเมื่อเปิดอีกครั้งแก้วน้ำจะกลับมา",
