    faq_a_routine_newme_sync: "เมื่อมี New Me ใน ⚙️ ของกิจวัตรของฉันจะมีสวิตช์ ‘ซิงค์กับ New Me’ เมื่อเปิด (ค่าเริ่มต้น) มื้ออาหารของ New Me วันนี้จะแสดงในวันของฉันและในกิจวัตรของฉัน – แทนที่มื้อในกิจวัตรที่ถูกซ่อนไว้ เมื่อปิด มื้ออาหารของ New Me จะออกจากทั้งสองที่ และกิจวัตรจะกลับเป็นเหมือนเดิมทุกอย่าง ไม่มีอะไรถูกลบ – เปิดอีกครั้งทุกอย่างจะกลับมา และจะถามว่าจะซ่อนมื้อไหนในกิจวัตร",
