    faq_a_food_list_languages: "รายการอาหารในตัวเริ่มต้นจากอาหารอิสราเอลพร้อมชื่อภาษาฮีบรู ในภาษาอื่นทั้งหมด อาหารแต่ละอย่างจะแสดงด้วยชื่อภาษาอังกฤษ และการค้นหาจะเจอทุกชื่อภาษาอังกฤษที่ระบบรู้จัก (เช่น 'broth' จะเจอ Clear soup) ส่วนอาหารที่มีแค่ชื่อภาษาฮีบรูจะไม่แสดงในรายการ อะไรที่ไม่มีในรายการก็เขียนด้วยคำของคุณเองได้เลย – การประมาณด้วย AI ใช้ได้ทุกภาษา",
    faq_q_food_list_languages: "ทำไมรายการอาหารในภาษาของฉันจึงแสดงชื่อภาษาอังกฤษ และมีอาหารน้อยกว่า?",
    settings_copyright_line: "© 2026 สงวนลิขสิทธิ์ แอปพัฒนาโดย eden zabari",
    workout_ready_replace_btn: "แทนที่",
    faq_a_sport_workout_ai: "ใน \"การออกกำลังกายของฉัน\" → ⋯ → \"แผนด้วย AI\" (และเมื่อตารางยังว่าง ก็มีที่ช่องข้างแผนสำเร็จรูปด้วย) ตอบด้วยการแตะไม่กี่ครั้ง ได้แก่ สัปดาห์ละกี่ครั้ง เมื่อไร สถานที่ ระดับ และเป้าหมาย เกือบทุกข้อมี \"อื่นๆ\" ด้วย และจะเพิ่มข้อความสั้นๆ หนึ่งบรรทัดก็ได้ เช่น เข่าไม่ค่อยดี หรืออยากวิ่ง 5 กม. ให้ได้ก่อนหน้าร้อน AI จะจัดทั้งสัปดาห์ให้ ทั้งประเภทการออกกำลังกาย วัน เวลา ระยะเวลา ความหนัก ท่าออกกำลังกาย และวันพัก ก่อนบันทึกจะมีตัวอย่างให้ดู: \"ใส่ในตารางของฉัน\" (แทนตารางเดิมหรือเพิ่มเข้าไป) \"ข้อเสนออื่น\" (ได้สูงสุด 3 ครั้ง) หรือ \"เปลี่ยนคำตอบ\" แผนตั้งใจให้พอดีๆ ไม่หักโหม และถ้าพูดถึงอาการเจ็บหรือบาดเจ็บ จะได้ตัวเลือกที่เบาลงพร้อมคำแนะนำให้ปรึกษาผู้เชี่ยวชาญ ฟีเจอร์นี้ใช้โควตา AI เดียวกับตารางเวลาและกิจวัตร: ใช้ฟรี 5 ครั้ง และ 60 ครั้งต่อเดือนกับพรีเมียม",
