    faq_a_sport_workout_jar: "การออกกำลังกายแต่ละประเภทมีดาวสีของตัวเอง เช่น วิ่งสีชมพู เดินสีเขียว ว่ายน้ำสีฟ้า ทุกครั้งที่บันทึกการออกกำลังกายในสัปดาห์นี้ ไม่ว่าจากตารางหรือแยกต่างหาก ดาวของมันจะหล่นลงในโหลด้านบนของ \"การออกกำลังกายของฉัน\" และโหลจะเต็มขึ้นเรื่อยๆ จนถึงเป้าหมายรายสัปดาห์ (แตะเพื่อเปลี่ยนเป้าหมาย) เมื่อถึงเป้าหมาย โหลจะเรืองแสง ส่วนโหลเล็กข้างๆ จะนับว่าเติมเต็มติดต่อกันมาแล้วกี่สัปดาห์",
