    faq_a_new_me_ai_menu: "ก่อนถึงเมนู แบบสอบถามจะถามว่ากินมื้อไหนบ้างและเวลาไหน (2 มื้อ + ของว่าง, 2 มื้อ + มื้อเย็นเบาๆ หรือทั้งสองอย่าง) ตอนเย็นกินอะไรเล็กๆ ไหมและกี่โมง ไม่กินอะไรบ้าง และดื่มกาแฟหรือชาแบบไหน จากนั้น AI จะจัด 3 ตัวเลือกให้ทุกมื้อ – แต่ละตัวเลือกมีขนาดตามส่วนของมื้อนั้นในวัน รวมทั้งวันจึงยังได้ 1,300 หรือ 1,500 พอดี – พร้อมไอเดียเครื่องดื่มที่บันทึกเป็นเครื่องดื่มประจำ เลือกเมนูโปรดได้สูงสุด 2 อย่างต่อมื้อ ตัวเลือกจากเมนูเดิมอยู่ข้างล่างทันที และใน 🔄 สลับ จะอยู่ต่อจากเมนูส่วนตัว 🔄 ตัวเลือกอื่น จะจัดชุดใหม่ (3 ครั้งต่อแบบสอบถาม) หากต้องการเปลี่ยนคำตอบหรือจัดเมนูใหม่ได้ทุกเมื่อ: ⚙️ การตั้งค่า → ✨ เมนูส่วนตัว (AI)",
