    faq_a_new_me_day_total: "ทุกวันรวมได้ตามแผนพอดี: มื้ออาหาร ประมาณ 150 แคลอรีสำหรับกาแฟและเครื่องดื่มระหว่างวัน และสิ่งที่เลือกไว้สำหรับตอนเย็น – กินอะไรเล็กๆ หรือดื่มอะไรสักอย่าง สำหรับตอนเย็น เลือกได้สูงสุด 3 อย่างที่ชอบ (เช่น กล้วย โยเกิร์ต หรือดาร์กช็อกโกแลต 2 ชิ้น หรือชาสมุนไพร ชาใส่นมนิดหน่อย หรือนมอุ่น) และแคลอรีของสิ่งเหล่านั้นจะหักจากมื้ออาหาร ทุกการเลือกปรับสมดุลเอง: ตัวเลือกที่เล็กหรือใหญ่กว่า มื้อที่ตัดออก มื้อเช้าเล็กและมื้อเล็กที่มาด้วยกัน หรือตอนเย็น – ส่วนต่างจะถูกเพิ่มหรือหักจากมื้ออาหาร แต่ละมื้อตามขนาดของมัน และใต้แต่ละมื้อจะเขียนว่าเท่าไร (+ หรือ −) และเพิ่มหรือลดอะไรได้ มื้อที่ติ๊กแล้วจะคงไว้ตามที่บันทึก ในแบบสอบถาม แต่ละมื้อจะแสดงการปรับของมัน และกล่องเล็กๆ จะแสดงมื้ออาหาร เครื่องดื่ม ตอนเย็น และยอดรวม วันนั้นอยากกินอย่างอื่นไหม? ให้ยอดรวมเท่ากับแคลอรีเดิมหรือน้อยกว่า",
