    faq_a_notes_sticky_look: "โน้ตคือรายการสั้นๆ ของการ์ดกระจก – 🎨 ที่ด้านบนของโน้ตใช้เปลี่ยนรูปแบบของโน้ตทั้งหมด: รายการ ปุ่มวันด้านบน และหน้าต่างที่ใช้เขียนโน้ต – กระจก รายการเรียบง่าย การ์ดโน้ต หรือเทปวาชิ โน้ตที่กำลังลากอยู่จะคงรูปแบบและสีของตัวเองไว้ตามเดิม แตะที่ข้อความของโน้ตเพื่อเปิด – ในนั้นแก้ไขได้ เปลี่ยนสีได้ และดูได้ว่าเขียนครั้งล่าสุดเมื่อไร แตะ ○ เมื่อทำเสร็จ ส่วน × จะย้ายไปคลังเก็บ (🗑️ ที่ด้านล่างของรายการเรียกคืนได้) ลากที่ ⠿ เพื่อเปลี่ยนลำดับ ย้ายไปไว้ใต้ “ไว้ทีหลัง” หรือวางบนวันด้านบน ! ทำเครื่องหมายโน้ตว่าด่วน – โน้ตจะค่อยๆ เลื่อนขึ้นไปอยู่แถวแรกๆ พร้อมป้ายเล็กๆ “ด่วน” แตะอีกครั้งเพื่อเอาออก",
