    faq_a_new_me_small_breakfast: "มื้อเช้าแบบเบา (ประมาณ 170 กิโลแคลอรี): พิต้าแป้งสเปลท์ (ไม่เกิน 100 กิโลแคลอรี) กับสเปรดหรือชีส พร้อมผัก 1 อย่าง – เลือกได้สูงสุด 3 อย่างที่ชอบ เช่น ช็อกโกแลตสเปรด 1 ช้อนชา เนยถั่ว 1 ช้อนชา หรือชีสแผ่น 1 แผ่น (ไขมันไม่เกิน 22%) เพราะมื้อนี้เล็ก จึงมี “และอีกหนึ่งมื้อเล็ก” มาด้วยในเวลาอื่น (เช่น หลังจากนั้นชั่วโมงครึ่ง 11:30 → 13:00 – เลือกเวลาอื่นได้): พิต้าอีกชิ้นกับสเปรด โยเกิร์ตโปรตีนกับผลไม้ ไรซ์เค้กกับชีส ซีเรียลกับนม หรือพิต้าครึ่งชิ้นกับไข่ – ไม่เกินประมาณ 200 กิโลแคลอรี พร้อม ✓ ของตัวเอง ส่วนที่ยังเหลือจะถูกแบ่งไปยังมื้ออื่น ๆ และแต่ละมื้อจะแสดงว่าได้เพิ่มเท่าไร ยอดรวมของวันจึงยังเท่ากับแผน เลือกได้ในแบบสอบถาม หรือเปลี่ยนเป็นมื้อนี้เฉพาะวันนี้ด้วย 🔄 – เช่น ตอนที่กินมื้อเช้าสาย",
