    faq_a_secret_room_yoga: "ปลายทางเดินในป่ามีประตูเรืองแสง และด้านหลังข้างน้ำตก เหล่าสัตว์ในป่า – ลูมี พัฟฟี่ นิกซี่ และสปาร์คเล็ต – นั่งอยู่บนเสื่อของตัวเองเป็นครึ่งวงกลม ส่วนฟลอรา ครูสอนโยคะ นั่งหันหน้าเข้าหาพวกมันบนเสื่อผืนเดียวที่วางอยู่บนก้อนหิน แตะที่ฟลอรา แล้วเธอจะลืมตา ทุกอย่างจะเคลื่อนเข้ามาใกล้ และบทสนทนาก็เริ่มขึ้นช้า ๆ โดยมีเวลาให้อ่าน – ฟลอราถามว่าทุกคนเป็นอย่างไรบ้าง สัตว์แต่ละตัวตอบในนามของตัวเอง (โดยมีรูปเล็ก ๆ ของผู้ที่กำลังพูดอยู่ข้างทุกบรรทัด) แล้วเธอก็ถามคุณว่าอยู่กับคนใกล้ตัวแล้วรู้สึกอย่างไร บทสนทนาจะดำเนินไปตามคำตอบของคุณ – คนดี คนที่ลำบากใจด้วย หรือความเหงาเล็กน้อย ทุกเส้นทางจบด้วยภารกิจเล็ก ๆ (เพิ่มลงในวันของฉันได้ทันที และเมื่อภารกิจคือการเขียนอะไรสักอย่าง จะมีที่ให้เขียน และสิ่งที่เขียนจะถูกบันทึกลงไดอารี่วิเศษ) และท่าโยคะพร้อมหายใจด้วยกันสามครั้ง ↩ ย้อนกลับหนึ่งขั้น และ ✦ เริ่มบทสนทนาใหม่ กุญแจดอกถัดไปเปิดน้ำตก: เมื่อนั่งบนก้อนหิน ทุกอย่างจะหายไป เหลือเพียงเสียงน้ำ เมื่อก้มมองสระน้ำ คำถามจะลอยขึ้นมาจากน้ำ – ตัวตนที่แท้จริงของคุณจะทำอะไรในวันนี้? – แล้วคำตอบจะกลายเป็นงานเล็ก ๆ ในวันของฉัน นี่คือช่วงเวลาอบอุ่น ไม่ใช่สิ่งทดแทนการพูดคุยกับผู้เชี่ยวชาญ",
