    routine_time_taken: "เวลานี้มีอย่างอื่นอยู่แล้ว: {title}",
    faq_a_new_me_times: "ในแบบสอบถามตอนเริ่มต้น และตั้งได้ทุกเมื่อในการตั้งค่า New Me → “เวลามื้ออาหาร” ถ้าในกิจวัตรมีเวลามื้ออาหารอยู่แล้ว ระบบจะดึงมาจากที่นั่น – และซ่อนมื้ออาหารของกิจวัตรแล้วแสดงมื้อของ New Me แทนได้ ถ้ายังไม่มี ก็เลือกว่าวันละกี่มื้อ (2 มื้อ + ของว่าง / 2 มื้อ + มื้อเย็นเบาๆ / 2 มื้อ + ของว่าง + มื้อเย็นเบาๆ) และแต่ละมื้อกี่โมง ถ้าเลือก “2 มื้อ + ของว่าง” จะเป็นมื้อกลางวันตอน 11:30 ของว่างตอน 16:00 และมื้อเย็นตอน 19:00 (เปลี่ยนได้ทุกมื้อ) นี่คือเวลามื้ออาหารของคุณทุกที่: ในทางเดิน ใน “วันของฉัน” ใน “กิจวัตรของฉัน” และในการแจ้งเตือน เลือกแบบไหนแคลอรีของวันก็เท่าเดิม ส่วนที่ตัดออกจะแบ่งไปให้มื้ออื่น",
