    faq_a_secret_room_diary: "เฉพาะคุณเท่านั้น หน้าไดอารี่ถูกบันทึกไว้ในบัญชี จึงอยู่ในทุกอุปกรณ์ และไม่มีใครอื่นเห็นได้ ไดอารี่วิเศษบนโต๊ะในห้องลับเปิดไดอารี่นี้ได้ ไดอารี่ในมุมดนตรีก็เช่นกัน ใต้หน้าใหม่มีตารางรายเดือนที่พับไว้: จุดจะบอกทุกวันที่มีหน้าไดอารี่ และการแตะวันจะเปิดหน้าของวันนั้น – ตรงนั้นลบหน้าได้ด้วย เมื่อไดอารี่เปิดแล้ว ก็เพิ่มลงในเมนูหลักได้ด้วย – ด้วยสวิตช์ในไดอารี่หรือในการตั้งค่าของ New Me",
    faq_a_secret_room_places: "แต่ละทางเข้าที่ประตูป่าเปิดด้วยกุญแจของตัวเอง ด้านหลังคือ: ระเบียงริมทะเล (บนโต๊ะเล็กมีตะเกียงอะลาดิน – แตะทีเดียว ภูตแห่งป่าจะลอยขึ้นมาจากตะเกียงท่ามกลางหมอกวิเศษ หมุนวนไปรอบๆ แล้วเริ่มบทสนทนาเกี่ยวกับความปรารถนาของคุณ – ดู “ภูตในตะเกียงทำอะไรได้บ้าง?”) กีตาร์และไดอารี่ (กีตาร์เล่นทำนองสั้นๆ ที่สงบแล้วหยุดเอง และแผ่นเสียงทั้งสามแผ่นที่แขวนอยู่บนต้นไม้ต่างก็เล่นทำนองที่มีมนตร์ขลังของตัวเอง – แตะอีกครั้งเพื่อหยุด – และไดอารี่บนตอไม้ไว้เขียน) ห้องหายใจ (ทะเลสาบอันเงียบสงบยามพระอาทิตย์ตก – โคมดอกบัวลอยอยู่บนน้ำ แตะที่โคม เขียนคำอธิษฐาน แล้วโคมจะลอยไกลออกไปพร้อมกัน ไกลลึกเข้าไปในทะเลสาบ – ใช้ไม้กายสิทธิ์เขียนบนทรายถึงสิ่งที่อยากปล่อยวาง แล้วมันจะอยู่ตรงนั้นจนกว่าคุณจะใช้นิ้วลบออก) และทางเดินในป่า (ทางเดินจะเปิดในตอนกลางคืน และแตะโคมไฟเพื่อสลับเป็นกลางวัน มีชิงช้าวิเศษแขวนอยู่กับกิ่งใหญ่ ม้านั่งไว้นั่ง และแตะป้ายเพื่อดูใกล้ ๆ – กระดานที่มีคำถามเล็ก ๆ หกข้อให้ติ๊ก) ทางเข้าที่ล็อกอยู่จะบอกว่ายังขาดกุญแจอีกกี่ดอก ที่ปลายทางเดิน ประตูเรืองแสงพาไปสู่โยคะข้างน้ำตก และจากที่นั่นไปสู่ตัวน้ำตกเอง",
