    faq_a_ai_chat: "แตะที่ฟองแชตแล้วหน้าแชตจะเปิดขึ้น เลือกสิ่งที่จะทำ – เพิ่มลงปฏิทิน สิ่งที่กินไป รูปสูตรอาหาร หรือตารางใหม่ – หรือจะพิมพ์ไปเลยก็ได้ แล้วผู้ช่วยจะเข้าใจเอง สำหรับปฏิทินเลือกได้ว่าครั้งเดียว ทุกสัปดาห์ หรือทุกวัน คำตอบจะมาในแชต และจากตรงนั้นไปต่อเรื่องอื่นหรือเปิดปฏิทิน / สิ่งที่กินไปได้เลย",
    faq_a_new_me_hall: "New Me เปิดขึ้นที่ประตูสู่ป่ามหัศจรรย์ และทุกทางเข้าตรงนั้นคือสถานที่หนึ่ง: ประตูกลมในต้นไม้ยักษ์พาเข้าสู่ห้องลับ ขอนไม้กลวงพาไปยังระเบียงริมทะเล บ้านเห็ดพาไปยังกีตาร์และไดอารี่ ซุ้มต้นหลิวเล็กพาไปยังห้องหายใจ ซุ้มต้นหลิวใหญ่พาไปยังทางเดินในป่า และซุ้มดอกไม้ที่มีบันไดพาปีนขึ้นสู่ดาดฟ้าดวงดาวเมื่อดาดฟ้าเปิดแล้ว ทางเข้าที่ล็อกอยู่จะมีแม่กุญแจ ตัวละครของคุณ Me ลอยอยู่บนทางเดิน และรอบๆ มีปุ่มเกม: ภารกิจถัดไป ชาเลนจ์ประจำสัปดาห์ เป้วิเศษที่มี New Me ทั้งหมด แผนที่โลก และเครื่องมือต่างๆ แตะกุญแจด้านบนจะอธิบายวิธีได้กุญแจ",
    faq_a_new_me_routine_meals: "เมื่อตั้งมื้ออาหารไว้ใน New Me และกิจวัตรของฉันก็มีมื้ออาหารด้วย New Me จะถามว่าจะซ่อนมื้อเหล่านั้นแล้วแสดงมื้อของ New Me แทนไหม – เพื่อไม่ให้มีอะไรแสดงซ้ำสองที่ จากนั้นกิจวัตรของฉันจะแสดงมื้อของ New Me ตามเวลาของแต่ละมื้อ พร้อม 💎 และ ✓ แตะที่ชื่อมื้อเพื่อเปิดหน้าต่างเลือกมื้ออื่นหรือเปลี่ยนเวลาของมื้อนั้น ได้เลยตรงนั้นเหนือกิจวัตร ไม่มีอะไรถูกลบ: นำกลับมาได้ที่ ⚙️ การตั้งค่า → มื้ออาหารในกิจวัตร ใน New Me หรือปิด “ซิงค์กับ New Me” ใน ⚙️ ของกิจวัตรของฉัน หากไม่มี New Me ที่ใช้งานอยู่ มื้อเหล่านั้นจะกลับมาเอง",
    faq_a_room_computer: "เป็นแชตเล็กๆ ที่เริ่มด้วย “วันนี้ที่ผ่านมาเป็นอย่างไรบ้าง?” – ดี ยุ่ง หรือหนัก – แล้วค่อยๆ ไปด้วยกันทีละขั้น จนถึงภารกิจเล็กๆ หนึ่งอย่างตอนท้าย (ซึ่งเพิ่มลงวันของฉันได้ทันที) แตะคำตอบหรือพิมพ์อย่างอิสระก็ได้ – สิ่งที่พิมพ์จะเชื่อมกับคำตอบที่ใกล้เคียงที่สุด “↩ ย้อนกลับ” ถอยกลับไปหนึ่งขั้นเพื่อตอบใหม่ และ “แชตใหม่” เริ่มต้นใหม่ได้ทุกเมื่อ หลังวันที่ยุ่งหรือหนัก กลับมาที่คอมพิวเตอร์ได้อีกในวันเดียวกัน: “กลับมาแล้ว...” จะต่อบทสนทนาเดิม ไฟสีเขียวด้านล่างใช้ปิดและเปิดคอมพิวเตอร์ ระบบเก็บเฉพาะตัวเลือก เฉพาะในอุปกรณ์นี้ และแค่ถึงสิ้นวัน",
