    faq_a_reminders_one_place: "การเตือนแต่ละครั้งจะมาครั้งเดียว ที่เดียว ถ้าแอปเปิดอยู่ตรงหน้าคุณ (บนคอมพิวเตอร์ iPad หรือโทรศัพท์) การเตือนจะขึ้นที่นั่น ถ้าไม่ใช่ จะมาเป็นการแจ้งเตือนที่โทรศัพท์เท่านั้น กด '✅ เสร็จแล้ว ขอบคุณ!' หรือ 'เข้าใจแล้ว!' ที่ไหนก็ได้ การเตือนจะปิดในทุกอุปกรณ์และจะไม่กลับมาอีก 'ยังไม่เสร็จ' คือเลื่อนการเตือน: จะกลับมาทุก 5 นาที แต่ละครั้งที่เดียว การติ๊ก ✓ ที่งานในรายการก็นับว่าเสร็จแล้วเช่นกัน ถ้าต้องการรับการแจ้งเตือนบนคอมพิวเตอร์และแท็บเล็ตด้วย ให้เปิด 'บนคอมพิวเตอร์และแท็บเล็ตด้วย' ใน การตั้งค่า > การแจ้งเตือน",
