    faq_a_good_things: "ตอนเย็น (ตั้งแต่ 18:00) จะมีปุ่มเล็กๆ แสดงใต้วันที่ เขียนเรื่องดีๆ ที่เกิดขึ้นวันนี้ได้สูงสุด 3 เรื่อง แค่เรื่องเดียวก็พอ ทุกอย่างจะถูกบันทึกไว้ และดูสิ่งที่เคยเขียนได้ใน 'วันก่อนๆ' 'ไม่ใช่คืนนี้' จะซ่อนปุ่มไว้จนถึงพรุ่งนี้ และปิดได้ทั้งหมดใน การตั้งค่า > การปรับแต่งและปฏิทิน",
    faq_a_home_countdown: "ติดดาว ⭐ ให้กิจกรรมในปฏิทิน (ดาวข้างกิจกรรมในรายการ) กิจกรรมที่ติดดาวซึ่งใกล้ที่สุดภายใน 100 วันข้างหน้าจะแสดงใต้วันที่ เช่น 'อีก 3 วัน · วันเกิดแม่' 'พรุ่งนี้ · …' หรือ 'วันนี้ · …' แตะเพื่อไปยังวันนั้นในปฏิทิน",
    faq_a_home_streak: "เป็นการนับว่ามี ✓ อย่างน้อยหนึ่งรายการติดต่อกันกี่วัน ไม่ว่าจะเป็นอะไรใน วันของฉัน กิจวัตรของฉัน เป้าหมายของฉัน หรือ New Me จะแสดงตั้งแต่ 2 วันขึ้นไป ถ้าวันนี้ยังไม่มี ✓ ความต่อเนื่องก็ยังไม่ขาด ยังมีเวลาอีกทั้งวัน และถ้าขาดไป มันก็แค่หายไปเงียบๆ โดยไม่ทำให้รู้สึกผิด",
    faq_a_home_weather: "เปิด 'สภาพอากาศบนท้องฟ้าของหน้าจอหลัก' ใน การตั้งค่า > การปรับแต่งและปฏิทิน แล้วอนุญาตตำแหน่ง จากนั้นท้องฟ้าของหน้าจอหลักจะแสดงสภาพอากาศจริงที่คุณอยู่ – ดวงอาทิตย์ (กลางคืนเป็นดวงจันทร์และดวงดาว) เมฆ ฝน หิมะ พายุ หรือหมอก – ในทุกธีม และอัปเดตประมาณทุก 40 นาที ตำแหน่งโดยประมาณ (ปัดเศษประมาณ 1 กม.) จะเก็บไว้ในอุปกรณ์ของคุณเท่านั้น และตรวจผ่านเซิร์ฟเวอร์ของเรากับ MET Norway ค่าเริ่มต้นคือปิด ใต้สวิตช์จะบอกว่าข้างนอกตอนนี้อากาศเป็นอย่างไร – เช่น ⛅ มีเมฆบางส่วน ท้องฟ้าจึงมีทั้งดวงอาทิตย์และเมฆ",
