    faq_a_home_focus: "แตะ ◎ ที่ด้านบนของหน้าจอหลัก: ทุกอย่างจะหายไปเหลือเพียงสิ่งเดียวสำหรับตอนนี้ – สิ่งที่มีในชั่วโมงนี้ หรือสิ่งถัดไปในรายการของวันนี้ – พร้อม ✓ ขนาดใหญ่ และบันทึกด่วน หลังจาก ✓ สิ่งถัดไปจะปรากฏขึ้น แตะ 'โหมดโฟกัส ✕' ที่ด้านบนเพื่อให้ทุกอย่างกลับมา",
    faq_a_home_search: "เปิดเมนู ☰ – ช่องค้นหาอยู่บนสุด พิมพ์อย่างน้อย 2 ตัวอักษร ผลลัพธ์มาจากบันทึก รายการซื้อของ ปฏิทิน สูตรอาหาร สมุด (ชื่อและข้อความในหน้า) เป้าหมาย ตาราง และหนังสือ จัดกลุ่มตามประเภท – แตะเพื่อไปที่นั่นทันที",
    faq_a_my_day: "วันของฉันรวมสิ่งที่เคยเป็น แอบดูวันนี้ และ กิจวัตรของฉัน ไว้บนไทม์ไลน์เดียว ที่ด้านล่างของหน้าจอหลักจะเห็นว่าทำไปแล้วเท่าไร อะไรคือตอนนี้หรือถัดไป (พร้อม ✓ ด่วน) และข้างชื่อหัวข้อมีน้ำหนึ่งแก้วด้วย +1 แตะ (หรือปัดขึ้น) เพื่อเปิดทั้งวัน: ด้านบนคือสิ่งที่ไม่ระบุเวลา ตามด้วยทุกอย่างตามชั่วโมง – งาน กิจกรรม และการประชุมจากปฏิทิน ช่วงเวลาประจำสัปดาห์ กิจวัตรของวันนี้ ก้าวเล็กๆ ของเป้าหมาย และมื้ออาหาร New Me – พร้อมเส้นบอกเวลาปัจจุบัน กรองได้ตามงาน กิจวัตร หรือการประชุมและกิจกรรม ✓ ที่นี่คือ ✓ เดียวกับที่อื่นทั้งหมด (กิจวัตรของฉัน เป้าหมายของฉัน ปฏิทิน) และทำให้ดอกเดซี่ที่มุมบาน 'แก้ไขกิจวัตร' จะเปิดกิจวัตรของฉัน (มีในเมนูด้วย) และ '＋ เพิ่มสำหรับวันนี้' จะเพิ่มงานสำหรับวันนี้ แตะที่หัวข้อ \"วันของฉัน\" (หรือแถบเล็กด้านบน) เพื่อปิดอีกครั้ง",
