    nm_plan_per_month: "/ เดือน",
    nm_plan_monthly_sub: "ยกเลิกได้ทุกเมื่อ",
    nm_plan_monthly: "รายเดือน",
    nm_plan_best: "คุ้มที่สุด",
    nm_plan_life_sub: "จ่ายครั้งเดียว – เป็นของคุณตลอดไป",
    nm_plan_life: "ตลอดชีพ",
    faq_a_new_me_tour: "ทันทีหลังซื้อและตอบแบบสอบถามสั้นๆ ทัวร์สั้นๆ จะพาดูเกม: แถบด้านบน ภารกิจถัดไป เครื่องมือทั้งสองข้าง ชาเลนจ์ประจำสัปดาห์ เป้วิเศษ แผนที่โลก ตัวละครของคุณ Me และประตู 1 สู่ห้องลับ ดูซ้ำได้ทุกเมื่อจาก ⚙️ การตั้งค่า > 🧭 ทัวร์ New Me – และเปลี่ยนชื่อเต็มจากแบบสอบถามได้ที่นั่นด้วย ก่อนซื้อ เมนูจะแสดง 🔒 ข้าง New Me และแตะเพื่อเปิดหน้าที่บอกทุกอย่างที่รวมอยู่",
    faq_q_new_me_tour: "มีคู่มือ New Me ไหม?",
    nm_locked_label: "ล็อกอยู่ – แตะเพื่อดูว่ามีอะไรบ้าง",
    nm_settings_tour: "ทัวร์ New Me",
    nm_tour_done_text: "ดูทัวร์ซ้ำได้ทุกเมื่อที่ ⚙️ การตั้งค่า",
    nm_tour_done_title: "พร้อมเริ่มแล้ว 💪",
    nm_tour_tiles_text: "เส้นทางและความสำเร็จ รายการซื้อของ การวัดสัดส่วน รูปภาพ ปฏิทินรายเดือน การแจ้งเตือน และ PDF ของเมนู",
    nm_tour_tiles_title: "อย่างอื่นทั้งหมด",
    nm_tour_challenges_text: "20 ชาเลนจ์ให้เลือก เริ่มเมื่อไรก็ได้ตามต้องการ – และมีของขวัญรออยู่ตอนท้าย",
    nm_tour_drinks_text: "กาแฟ ชา หรือเครื่องดื่มอื่นๆ – คำนวณแคลอรีให้อัตโนมัติ แตะเพื่อเปิด",
    nm_tour_swap_text: "🔄 สลับมื้อ – จากเมนู จากมื้อที่บันทึกไว้ หรือเขียนด้วย AI สำหรับวันนี้หรือตั้งแต่นี้ไป ⭐ บันทึกไว้ ➖ เอาออกจากเมนู",
    nm_tour_menu_text: "มื้ออาหารของวันนี้ ✓ เมื่อกินมื้อนั้นแล้ว – จะถูกเพิ่มลงในตัวติดตามมื้ออาหารรายวันโดยอัตโนมัติ",
    nm_tour_ring_text: "วงแหวนแสดงว่าวันนี้เหลืออีกเท่าไรจากแผน การออกกำลังกายช่วยเพิ่มให้",
