    faq_a_new_me_challenges: "ใน 🏆 ชาเลนจ์ มี 20 ชาเลนจ์: ชาเลนจ์ใหญ่ 10 อัน (เช่น 5 วันไม่กินน้ำตาล หนึ่งสัปดาห์ไม่กินคาร์บ หรือลด 4 กก. ในหนึ่งเดือน – ทุกวันแคลอรีติดลบ ออกกำลังกาย และไม่มีน้ำตาล) และมินิชาเลนจ์ 10 อัน – นิสัยเล็กๆ หนึ่งสัปดาห์ เช่น กาแฟอบเชยไม่ใส่น้ำตาล เมื่อเลือกชาเลนจ์จะมีคำถามว่าจะเริ่มเมื่อไหร่: วันนี้ พรุ่งนี้ สัปดาห์หน้า หรือวันอื่น ชาเลนจ์ใหญ่หนึ่งอันและมินิชาเลนจ์หนึ่งอันทำพร้อมกันได้ ชาเลนจ์ที่กำลังทำจะอยู่บนสุดของเมนูและใน วันของฉัน พร้อม ✓ สำหรับวันนั้น ทุกสัปดาห์ของชาเลนจ์มีวันพัก (🍕) หนึ่งวันที่ไม่ทำให้ขาดตอน และวันที่ไม่ได้ติ๊กนับเป็นวันพัก – ติ๊กได้ทั้งวันนี้และเมื่อวาน บางวันติ๊กให้อัตโนมัติ: การออกกำลังกาย 20 นาทีใน ติดตามการออกกำลังกาย หรือมื้อในเมนูที่ได้ ✓ ทุกชาเลนจ์มี ⓘ บอกว่าอะไรนับบ้าง (เช่น รายการคาร์บทั้งหมด) – ทั้งในชาเลนจ์และข้างๆ ในวันของฉัน ด้านล่าง ใน 🌱 การพัฒนาตนเอง มีชาเลนจ์เล็กๆ หนึ่งสัปดาห์อีก 48 อย่าง (ไม่นับรวมใน 20 ชาเลนจ์นี้) – ดู “ชาเลนจ์ประจำสัปดาห์คืออะไร?”",
