    faq_a_workout_calories: "นับ ทุกการออกกำลังกายจะได้ค่าประมาณแคลอรีที่เผาผลาญ – ตามประเภท ระยะเวลา และน้ำหนักล่าสุด (วิ่งและปั่นจักรยานยังคิดตามความเร็วเมื่อใส่ระยะทาง) แสดงในรายการออกกำลังกายและสรุปรายเดือน (เผาผลาญ) และเพิ่มเข้างบแคลอรีของวันนั้น: ในตัวติดตามมื้ออาหารรายวัน ตัวชี้วัดแคลอรีและน้ำหนัก และวงแหวนของ New Me เป็นค่าประมาณ จึงแสดงพร้อม ~",
