    recipe_add_to_presets_btn: "⭐ เพิ่มในมื้ออาหารที่บันทึกไว้",
    faq_a_my_notebooks: "สมุดอยู่ในช่องต่าง ๆ ของกระเป๋าของฉัน แต่ละเล่มมีปกที่คุณออกแบบเอง – สี ลาย และสติกเกอร์ ข้างในเป็นกระดาษสีครีมและพลิกหน้าได้เหมือนสมุดจริง: ปัดไปด้านข้างหรือแตะหน้าในแถบหน้าด้านล่าง ซึ่งมี ＋ ไว้เพิ่มหน้าใหม่ – แบบมีเส้น (สำหรับเขียน) แบบตาราง (สำหรับคณิตและสเก็ตช์) แบบเปล่า (สำหรับวาด) หรือรายการตรวจสอบ ในหน้าวาดรูป เครื่องมือจะลอยอยู่ที่ด้านล่างของหน้า: ปากกา ปากกาเน้นข้อความ ปากกาเน้นข้อความหัวตัด และยางลบ วงกลมสีสำหรับเลือกสีและความหนา เลิกทำ และสติกเกอร์ 🔍 เปิดสารบัญพร้อมการค้นหา 🔖 ใช้คั่นหน้าที่สมุดจะเปิดขึ้นมา และใน ⋯ มีปกและรายละเอียด การเปลี่ยนชื่อหน้า การล้างภาพวาด และการลบหน้า การ์ด ✅ งาน ด้านบนของกระเป๋าของฉันเปิดรายการงานของคุณ พร้อม 🪄 แบ่งงานอัจฉริยะสำหรับงานใหญ่ สมุดเป็นส่วนหนึ่งของพรีเมียม ส่วนรายการงานใช้ได้ฟรี",
