    faq_a_reminder_snooze: "ทำงานเหมือนการเลื่อนปลุก: การเตือนครั้งถัดไปจะมาใน 5 นาที และจะกลับมาทุก 5 นาทีจนกว่าจะแตะ '✅ เสร็จแล้ว ขอบคุณ!' หรือ 'เข้าใจแล้ว!' (สูงสุด 6 ครั้งหากไม่มีการตอบสนอง) ในการแจ้งเตือนบนโทรศัพท์ ⏰ จะเลื่อนการเตือนออกไป และ ✅ จะทำเครื่องหมายว่างานเสร็จแล้วโดยไม่ต้องเปิดแอป ส่วนการแตะการแจ้งเตือนหรือปัดทิ้งจะนับเป็น 'เข้าใจแล้ว!' การเลื่อนเตือนทำงานได้แม้แอปจะปิดอยู่ และหากงานถูกทำเครื่องหมายว่าเสร็จแล้วในระหว่างนั้น การเตือนจะหยุดเอง",
