    nm_slot_drinks: "เครื่องดื่ม",
    faq_a_new_me_tracking: "แตะภารกิจถัดไปที่ด้านบนของ New Me แล้วแตะ ✓ กินแล้ว เพื่อบันทึกว่ากินมื้อถัดไปแล้ว – เมนูเต็มพร้อม ✓ ทุกมื้ออยู่ใน “ทั้งวัน” ด้านข้าง และมื้อของวันนี้ยังแสดงใน วันของฉัน บนหน้าจอหลักด้วย – แตะมื้อใดมื้อหนึ่งตรงนั้น (หรือวางเมาส์ไว้เหนือมื้อนั้น) จะเห็นชัดเจนว่าต้องกินอะไร พร้อม ✓ และ สลับ ทุกอย่างซิงค์กับตัวติดตามมื้ออาหารรายวัน: มื้อตามแผน เครื่องดื่ม และทุกอย่างที่เพิ่มจากที่อื่น (เช่น กาแฟจากการเพิ่มด่วน) นับรวมกันทั้งใน New Me และวันของฉัน – สิ่งที่พิมพ์ไว้แล้วจะไม่ถูกเขียนทับ และการเอา ✓ ออกจะลบแค่ส่วนของ New Me เมื่อติ๊กอาหารครบทุกมื้อของวันนี้จะมีการฉลองเล็กๆ ใน “เครื่องดื่ม” ให้บันทึกเครื่องดื่มของวัน – รวมกันไม่เกิน ~150 กิโลแคลอรี หรือประมาณ 3 แก้ว แก้วละไม่เกิน ~50 กิโลแคลอรี แค่พิมพ์ชื่อเครื่องดื่ม AI จะเติมแคลอรีให้อัตโนมัติ สองแถวของกาแฟ/ชายังมีช่อง “ใส่นมไหม? เท่าไร?” (เช่น “นิดหน่อย” หรือ “50 มล.”) และการคำนวณจะอัปเดต ตัวเลขเปลี่ยนได้ทั้งก่อนและหลังเพิ่ม เครื่องดื่มที่มีชื่อและแคลอรีจะบันทึกอัตโนมัติทันทีที่ไปต่อ – จะแตะ เพิ่ม หรือไม่ก็ได้ แตะ ☆ ข้างเครื่องดื่มเพื่อบันทึกเป็นเครื่องดื่มประจำ – เครื่องดื่มประจำจะแสดงเป็นปุ่มบนการ์ดเครื่องดื่ม และแตะครั้งเดียวก็เพิ่มลงวันได้ ⭐ บันทึกมื้อเป็นมื้อที่บันทึกไว้ “ตารางรายวัน” แสดงสิ่งที่กินพร้อมแคลอรีและโปรตีน ปุ่ม 💎 เล็กๆ ข้างโหมดโฟกัสที่ด้านบนของหน้าจอหลักเปิด New Me ได้โดยตรง ค่าแคลอรีและโปรตีนเป็นค่าประมาณจาก AI และอาจคลาดเคลื่อนได้ กินไม่หมด? ใต้มื้อที่ติ๊กแล้ว “กินไม่หมด?” จะหักออกหนึ่งในสี่ ครึ่งหนึ่ง หรือสามในสี่ของปริมาณ – หรือตามที่เขียนไว้ โดยคำนวณให้ – และแคลอรีของวันจะอัปเดต",
    faq_q_new_me_tracking: "✓ การสลับ และแคลอรีใน New Me ทำงานอย่างไร?",
    faq_a_new_me_what: "New Me เป็นโปรแกรมเมนูรายวันแยกต่างหาก มีสองแผนสำเร็จรูป – 1,300 หรือ 1,500 แคลอรี – ประกอบด้วยมื้อหลัก 2 มื้อและของว่าง 2 มื้อ แต่ละมื้อมี 3 ตัวเลือก รวมพรีเมียมทั้งหมดไว้แล้ว ราคา: $11.99 ต่อเดือน (ยกเลิกได้ทุกเมื่อ) หรือ $99.99 ครั้งเดียวตลอดชีพ เปิดได้จาก 💎 New Me ในเมนู ก่อนเริ่มจะมีแบบสอบถามสั้นๆ ที่เริ่มด้วยข้อจำกัดความรับผิดทางการแพทย์ที่ต้องยอมรับ โปรแกรมนี้เป็นข้อมูลทั่วไปเท่านั้น และไม่ได้แทนแพทย์หรือนักกำหนดอาหารทางคลินิก",
