    nm_disclaimer_p2: "2. การเลือกแผน การเลือกแผน 1,300 แคลอรีหรือแผน 1,500 แคลอรีเป็นไปตามดุลยพินิจและความรับผิดชอบของผู้ใช้แต่เพียงผู้เดียว ขอแนะนำให้ปรึกษาแพทย์หรือนักกำหนดอาหารทางคลินิกก่อนเริ่มการควบคุมอาหารแบบจำกัดแคลอรีใด ๆ",
